  'faq2-a' => 'ऐसा तब होता है जब वर्ड के मूल निर्यात के बजाय प्रिंट टू पीडीएफ विधि का उपयोग किया जाता है। पीडीएफ में प्रिंट करने से पूरा पृष्ठ एक निश्चित रिज़ॉल्यूशन पर रैस्टराइज़ हो जाता है, जिससे छवि गुणवत्ता ख़राब हो जाती है। फ़ाइल का उपयोग करें, फिर निर्यात करें, फिर इसके बजाय वर्ड में पीडीएफ/एक्सपीएस बनाएं, जो छवियों को उनके मूल रिज़ॉल्यूशन में संरक्षित करता है।',
  'faq3-q' => 'क्या मैं पासवर्ड से सुरक्षित वर्ड दस्तावेज़ को पीडीएफ में बदल सकता हूँ?',
  'faq3-a' => 'हाँ, लेकिन आपको पहले Word दस्तावेज़ को खोलना होगा, जिसके लिए पासवर्ड की आवश्यकता होती है। एक बार जब दस्तावेज़ वर्ड में खुल जाए, तो आप इसे सामान्य रूप से पीडीएफ में निर्यात कर सकते हैं। जब तक आप अलग से पीडीएफ सुरक्षा नहीं जोड़ते, परिणामी पीडीएफ को वर्ड दस्तावेज़ की पासवर्ड सुरक्षा विरासत में नहीं मिलेगी।',
  'faq4-q' => 'क्या पीडीएफ में कनवर्ट करने से हाइपरलिंक सुरक्षित रहते हैं?',
  'faq4-a' => 'हाँ, Word के मूल निर्यात या गुणवत्ता वाले ऑनलाइन कनवर्टर का उपयोग करते समय। वर्ड दस्तावेज़ में हाइपरलिंक परिणामी पीडीएफ में क्लिक करने योग्य बने रहते हैं। यदि आपके हाइपरलिंक संरक्षित नहीं हैं, तो जांचें कि आप प्रिंट ड्राइवर विधि के बजाय मूल निर्यात विकल्प का उपयोग कर रहे हैं।',
);
